import SwiftUI

struct PricingView:View{
    let onCreate:()->Void
    var body:some View{ScrollView{VStack(spacing:20){TallyLogo().padding(.top,20);Text("Simple, transparent pricing").font(.system(size:38,weight:.bold)).multilineTextAlignment(.center).padding(.top,25);Text("Start free. Upgrade when you need more power.").foregroundStyle(.secondary).multilineTextAlignment(.center).padding(.bottom,12);PlanCard(name:"Free",price:"€0",period:"forever",features:["Unlimited forms","Unlimited submissions (fair use)","All input blocks","Conditional logic","GDPR friendly"],pro:false,onCreate:onCreate);PlanCard(name:"Pro",price:"€29",period:"per month",features:["Everything in Free","Remove branding","Custom domains","Team collaboration","Priority support"],pro:true,onCreate:onCreate)}.padding(24).padding(.bottom,40)}.background(Color.tallyCanvas)}
}
private struct PlanCard:View{let name,price,period:String;let features:[String];let pro:Bool;let onCreate:()->Void;var body:some View{VStack(alignment:.leading,spacing:13){Text(name).font(.title2.bold());HStack(alignment:.lastTextBaseline){Text(price).font(.system(size:43,weight:.bold));Text("/ \(period)").foregroundStyle(.secondary)};ForEach(features,id:\.self){Label($0,systemImage:"checkmark").font(.subheadline)};Button(pro ? "Try Pro":"Get started free",action:onCreate).buttonStyle(PrimaryButtonStyle(dark:pro)).padding(.top,10)}.padding(26).frame(maxWidth:.infinity,alignment:.leading).background(.white,in:RoundedRectangle(cornerRadius:19)).overlay{RoundedRectangle(cornerRadius:19).stroke(pro ? Color.tallyPink:.black.opacity(.08),lineWidth:pro ? 2:1)}}}
